// FUNCTION: BFME2 0x000FDF4C size=181 name=?bindTrack@WaterTracksRenderSystem@@QAEPAVWaterTracksObj@@W4waveType@@@Z evidence=N:ledger tier=B hypothesis:Z
WaterTracksObj *WaterTracksRenderSystem::bindTrack(waveType type)
{
	WaterTracksObj *mod, *nextmod, *prevmod;

	mod = m_freeModules;
	if (mod)
	{
		// take module off the free list
		if (mod->m_nextSystem)
			mod->m_nextSystem->m_prevSystem = mod->m_prevSystem;
		if (mod->m_prevSystem)
			mod->m_prevSystem->m_nextSystem = mod->m_nextSystem;
		else
			m_freeModules = mod->m_nextSystem;

		mod->m_type = type;

		// put module on the used list (sorted next to similar types)
		nextmod = NULL, prevmod = NULL;
		for (nextmod = m_usedModules; nextmod; prevmod = nextmod, nextmod = nextmod->m_nextSystem)
		{
			if (nextmod->m_type == type)
			{	// found start of other tracks using the same type, insert the new one here.
				mod->m_nextSystem = nextmod;
				mod->m_prevSystem = prevmod;
				nextmod->m_prevSystem = mod;
				if (prevmod)
				{
					prevmod->m_nextSystem = mod;
				}
				else
					m_usedModules = mod;
				break;
			}
		}

		if (nextmod == NULL)
		{	// track with a new type. Add to top of list.
			mod->m_nextSystem = m_usedModules;
			if (m_usedModules)
				m_usedModules->m_prevSystem = mod;
			m_usedModules = mod;
		}

		mod->m_bound = true;
	}

	nextmod = m_usedModules;

	while (nextmod)
	{
		nextmod->m_elapsedMs = nextmod->m_initTimeOffset;
		nextmod = nextmod->m_nextSystem;
	}

	return mod;
}

// FUNCTION: BFME2 0x000FE001 size=100 name=?releaseTrack@WaterTracksRenderSystem@@QAEXPAUFeNode@@@Z evidence=N:ledger tier=B hypothesis:Z
void WaterTracksRenderSystem::unbindTrack(WaterTracksObj *mod)
{
	if (mod == NULL)
		return;

	// remove module from used list
	if (mod->m_nextSystem)
		mod->m_nextSystem->m_prevSystem = mod->m_prevSystem;
	if (mod->m_prevSystem)
		mod->m_prevSystem->m_nextSystem = mod->m_nextSystem;
	else
		m_usedModules = mod->m_nextSystem;

	// add module to free list
	mod->m_prevSystem = NULL;
	mod->m_nextSystem = m_freeModules;
	if (m_freeModules)
		m_freeModules->m_prevSystem = mod;
	m_freeModules = mod;
}

// FUNCTION: BFME2 0x000FE065 size=291 name=?ReAcquireResources@WaterTracksRenderSystem@@QAEXXZ evidence=N:ledger tier=B hypothesis:Z
void WaterTracksRenderSystem::ReAcquireResources(void)
{
	Int i, j, k;

	if (m_indexBuffer)
	{
		m_indexBuffer->Release_Ref();
		m_indexBuffer = NULL;
	}
	if (m_vertexBuffer)
	{
		m_vertexBuffer->Release_Ref();
		m_vertexBuffer = NULL;
	}

	// (y-1) strips of 2x vertices plus two indices joining each strip to the next, less the last join
	Int idxCount = (m_stripSizeY - 1) * (m_stripSizeX * 2 + 2) - 2;

	m_indexBuffer = new DX8IndexBufferClass(idxCount);

	{
		DX8IndexBufferClass::WriteLockClass lockIdxBuffer(m_indexBuffer);
		UnsignedShort *ib = lockIdxBuffer.Get_Index_Array();

		for (i = 0, j = 0, k = 0; i < idxCount; j++)
		{
			for (; k < (m_stripSizeX * (j + 1)); k++, i += 2)
			{
				ib[i] = (UnsignedShort)k + m_stripSizeX;
				ib[i + 1] = (UnsignedShort)k;
			}
			// degenerate triangles join this strip to the next row
			if (i < idxCount)
			{
				ib[i] = k - 1;
				ib[i + 1] = k + m_stripSizeX;
				i += 2;
			}
		}
	}

	m_vertexBuffer = new DX8VertexBufferClass(0x142, m_stripSizeX * m_stripSizeY * WATER_VB_PAGES, DX8VertexBufferClass::USAGE_DYNAMIC);
	m_batchStart = 0;
}

// FUNCTION: BFME2 0x000FE188 size=36 name=?rva000FE188@WaterTracksRenderSystem@@QAEXXZ evidence=?:placeholder tier=B hypothesis:Z
void WaterTracksRenderSystem::rva000FE188(void)
{
	WaterTracksObj *nextMod;
	WaterTracksObj *mod = m_usedModules;

	// release unbound tracks that may still be fading out
	while (mod)
	{
		nextMod = mod->m_nextSystem;
		mod->m_bound = false;
		unbindTrack(mod);
		mod = nextMod;
	}
	m_usedModules = NULL;
}

// FUNCTION: BFME2 0x000FE1AC size=91 name=?rva000FE1AC@WaterTracksRenderSystem@@QAEXXZ evidence=?:placeholder tier=B hypothesis:K
void WaterTracksRenderSystem::rva000FE1AC(void)
{
	static int iLastTime = timeGetTime();
	WaterTracksObj *mod = m_usedModules;
	WaterTracksObj *nextMod;

	int timeDiff = timeGetTime() - iLastTime;
	iLastTime += timeDiff;

	while (mod)
	{
		nextMod = mod->m_nextSystem;
		if (mod->m_bound)
			mod->m_elapsedMs += 33;
		else
			unbindTrack(mod);
		mod = nextMod;
	}
}

// FUNCTION: BFME2 0x000FE207 size=137 name=?findTrack@WaterTracksRenderSystem@@QAEPAUFeNode@@PBM0H@Z evidence=N:ledger tier=B hypothesis:K
WaterTracksObj *WaterTracksRenderSystem::findTrack(Vector2 &start, Vector2 &end, waveType type)
{
	WaterTracksObj *mod = m_usedModules;

	while (mod)
	{
		if (mod->m_initEndPos == end &&
			mod->m_initStartPos == start &&
			mod->m_type == type)
			return mod;
		mod = mod->m_nextSystem;
	}
	return NULL;
}

